15	
16	// 用量导入文件（CSV，UTF-8，首行为固定表头，之后每行一条用量）：
17	//
18	//	usage_id,customer_id,time,quantity
19	//	u-001,cust-1,2026-09-15T10:00:00Z,100
20	//
21	//	usage_id   全局唯一用量标识，非空
22	//	customer_id 必须是已登记的客户标识
23	//	time       RFC3339 时间，如 2026-09-15T10:00:00Z 或 2026-09-15T18:00:00+08:00
24	//	quantity   正整数数量（有符号 64 位整数范围内）
25	const usageHeader = "usage_id,customer_id,time,quantity"
26	
27	// runCmd 解析并执行子命令。业务/用法错误通过 error 返回，由 main 统一
28	// 写入标准错误并以非零状态退出。
29	func runCmd(args []string, dataDir string) error {
30		switch args[0] {
31		case "customer":
32			if len(args) < 2 {
33				return usageError("缺少子命令，应为：customer add <标识> <名称> <单价分> 或 customer add-plan <标识> <名称> <方案标识>")
34			}
35			switch args[1] {
36			case "add":
37				if len(args) != 5 {
38					return usageError("用法：customer add <标识> <名称> <单价分>")
39				}
40				return cmdCustomerAdd(dataDir, args[2], args[3], args[4])
41			case "add-plan":
42				if len(args) != 5 {
43					return usageError("用法：customer add-plan <标识> <名称> <方案标识>")
44				}
45				return cmdCustomerAddPlan(dataDir, args[2], args[3], args[4])
46			default:
47				return usageError("未知 customer 子命令 %q；可用：add、add-plan", args[1])
48			}
49	
50		case "plan":
51			if len(args) < 2 {
52				return usageError("缺少子命令，应为：plan add|show|list|change|schedule ...")
53			}
54			switch args[1] {
55			case "add":
56				if len(args) < 5 {
57					return usageError("用法：plan add <标识> <名称> <上限:单价分>... <-:单价分>")
58				}
59				return cmdPlanAdd(dataDir, args[2], args[3], args[4:])
60			case "show":
61				if len(args) != 3 {
62					return usageError("用法：plan show <标识>")
63				}
64				return cmdPlanShow(dataDir, args[2])
65			case "list":
66				if len(args) != 2 {
67					return usageError("用法：plan list")
68				}
69				return cmdPlanList(dataDir)
70			case "change":
71				if len(args) != 6 {
72					return usageError("用法：plan change <客户标识> <YYYY-MM> <方案标识> <原因>")
73				}
74				return cmdPlanChange(dataDir, args[2], args[3], args[4], args[5])
75			case "schedule":
76				if len(args) != 3 && len(args) != 4 {
77					return usageError("用法：plan schedule <客户标识> [YYYY-MM]")
78				}
79				month, hasMonth := "", false
80				if len(args) == 4 {
81					month, hasMonth = args[3], true
82				}
83				return cmdPlanSchedule(dataDir, args[2], month, hasMonth)
84			default:
85				return usageError("未知 plan 子命令 %q；可用：add、show、list、change、schedule", args[1])
86			}
87	
88		case "usage":
89			if len(args) < 2 {
90				return usageError("缺少子命令，应为：usage import <文件>")
91			}
92			switch args[1] {
93			case "import":
94				if len(args) != 3 {
95					return usageError("用法：usage import <文件>（- 表示标准输入）")
96				}
97				return cmdUsageImport(dataDir, args[2])
98			default:
99				return usageError("未知 usage 子命令 %q；可用：import", args[1])
100			}
101	
102		case "bill":
103			if len(args) < 2 {
104				return usageError("缺少子命令，应为：bill settle|show|adjust|revoke|pay|remit|correct|unpay|ledger ...")
105			}
106			switch args[1] {
107			case "settle":
108				if len(args) != 4 {
109					return usageError("用法：bill settle <客户标识> <YYYY-MM>")
110				}
111				return cmdBillSettle(dataDir, args[2], args[3])
112			case "show":
113				if len(args) != 4 {
114					return usageError("用法：bill show <客户标识> <YYYY-MM>")
115				}
116				return cmdBillShow(dataDir, args[2], args[3])
117			case "adjust":
118				if len(args) != 7 {
119					return usageError("用法：bill adjust <客户标识> <YYYY-MM> <调整标识> <金额分> <原因>")
120				}
121				return cmdBillAdjust(dataDir, args[2], args[3], args[4], args[5], args[6])
122			case "revoke":
123				if len(args) != 4 {
124					return usageError("用法：bill revoke <调整标识> <原因>")
125				}
126				return cmdBillRevoke(dataDir, args[2], args[3])
127			case "pay":
128				if len(args) != 7 {
129					return usageError("用法：bill pay <客户标识> <YYYY-MM> <收款标识> <金额分> <备注>")
130				}
131				return cmdBillPay(dataDir, args[2], args[3], args[4], args[5], args[6])
132			case "remit":
133				if len(args) < 6 {
134					return usageError("用法：bill remit <客户标识> <收款标识> <总金额分> <备注> <YYYY-MM:金额分> [更多 月份:金额 ...]")
135				}
136				return cmdBillRemit(dataDir, args[2], args[3], args[4], args[5], args[6:])
137			case "correct":
138				if len(args) < 6 {
139					return usageError("用法：bill correct <收款标识> <更正标识> <原因> <YYYY-MM:金额分> [更多 月份:金额 ...]")
140				}
141				return cmdBillCorrect(dataDir, args[2], args[3], args[4], args[5:])
142			case "unpay":
143				if len(args) != 4 {
144					return usageError("用法：bill unpay <收款标识> <原因>")
145				}
146				return cmdBillUnpay(dataDir, args[2], args[3])
147			case "ledger":
148				if len(args) != 4 && len(args) != 5 {
149					return usageError("用法：bill ledger <客户标识> <YYYY-MM> [截止操作序号]")
150				}
151				cutoff, hasCutoff := "", false
152				if len(args) == 5 {
153					cutoff, hasCutoff = args[4], true
154				}
155				return cmdBillLedger(dataDir, args[2], args[3], cutoff, hasCutoff)
156			default:
157				return usageError("未知 bill 子命令 %q；可用：settle、show、adjust、revoke、pay、remit、correct、unpay、ledger", args[1])
158			}
159	
160		default:
161			return usageError("未知命令 %q；可用：customer、plan、usage、bill", args[0])
162		}
163	}
164	
165	type usageErrorf string
166	
167	func (e usageErrorf) Error() string { return string(e) }
168	
169	func usageError(format string, a ...any) error {
170		return usageErrorf(fmt.Sprintf(format, a...))
171	}
172	
173	func cmdCustomerAdd(dir, id, name, priceText string) error {
174		if strings.TrimSpace(id) == "" {
175			return fmt.Errorf("客户标识不能为空")
176		}
177		if strings.TrimSpace(name) == "" {
178			return fmt.Errorf("客户名称不能为空")
179		}
180		price, err := parsePrice(priceText)
181		if err != nil {
182			return err
183		}
184	
185		s, err := loadStore(dir)
186		if err != nil {
187			return err
188		}
189		if _, exists := s.Customers[id]; exists {
190			return fmt.Errorf("客户标识 %q 已存在，客户单价创建后不可修改", id)
191		}
192		s.Customers[id] = &customer{ID: id, Name: name, Price: price}
193		if err := s.save(); err != nil {
194			return err
195		}
196		fmt.Fprintf(stdout, "已登记客户 %q（%s），固定单价 %d 分（%s）\n", id, name, price, moneyFen(price))
197		return nil
198	}
199	
200	func parsePrice(text string) (int64, error) {
201		text = strings.TrimSpace(text)
202		price, err := strconv.ParseInt(text, 10, 64)
203		if err != nil {
204			return 0, fmt.Errorf("单价 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
205		}
206		if price < 0 {
207			return 0, fmt.Errorf("单价必须是非负整数分，收到 %d", price)
208		}
209		return price, nil
210	}
211	
212	// parsedRow 是导入文件中一行解析后的候选用量。
213	type parsedRow struct {
214		line int // 文件中的行号（含表头），用于报错定位
215		rec  usageRecord
216		t    time.Time
217	}
218	
219	func cmdUsageImport(dir, file string) error {
220		var reader io.ReadCloser
221		var source string
222		if file == "-" {
223			reader = io.NopCloser(os.Stdin)
224			source = "标准输入"
225		} else {
226			f, err := os.Open(file)
227			if err != nil {
228				return fmt.Errorf("无法打开用量文件 %s: %w", file, err)
229			}
230			reader = f
231			source = file
232		}
233		defer reader.Close()
234	
235		rows, parseErrs := parseUsageFile(reader)
236	
237		s, err := loadStore(dir)
238		if err != nil {
239			return err
240		}
241	
242		// 先校验：任何问题都在此阶段收集，全部通过后才一次性修改并保存，
243		// 保证“整批导入先校验再生效”，失败不留下任何新用量。
244		var problems []string
245		problems = append(problems, parseErrs...)
246	
247		accepted := make(map[string]*parsedRow) // 本批内首次出现、内容确定的记录
248		var ordered []*parsedRow
249		newCount, dupCount := 0, 0
250	
251		for _, r := range rows {
252			cust, ok := s.Customers[r.rec.CustomerID]
253			if !ok {
254				problems = append(problems, fmt.Sprintf("第 %d 行：客户标识 %q 不存在", r.line, r.rec.CustomerID))
255				continue
256			}
257			// 金额可行性预检：固定单价客户检查 数量×单价；阶梯客户按记录时间
258			// 换算的 UTC 月份的有效方案，以单条数量从零计价，检查分段金额不
259			// 溢出（金额单位：分）。
260			if cust.PlanID == "" {
261				if _, err := mul64(r.rec.Quantity, cust.Price); err != nil {
262					problems = append(problems, fmt.Sprintf("第 %d 行：数量 %d × 单价 %d 金额溢出有符号 64 位整数范围", r.line, r.rec.Quantity, cust.Price))
263					continue
264				}
265			} else {
266				rec := r.rec
267				month := r.t.UTC().Format("2006-01")
268				planID := s.effectivePlanID(cust, month)
269				if _, err := tieredPrice(s.Plans[planID].Tiers, []*usageRecord{&rec}); err != nil {
270					problems = append(problems, fmt.Sprintf("第 %d 行：按 %s 月有效方案 %q 对单条数量从零计价失败：%v", r.line, month, planID, err))
271					continue
272				}
273			}
274	
275			// 去重判定同时对“库中已有”和“本文件内已出现”生效。
276			var existing *usageRecord
277			if inStore, ok := s.Usage[r.rec.ID]; ok {
278				existing = inStore
279			} else if inBatch, ok := accepted[r.rec.ID]; ok {
280				existing = &inBatch.rec
281			}
282	
283			if existing != nil {
284				if !sameUsage(existing, &r.rec, r.t) {
285					problems = append(problems, fmt.Sprintf("第 %d 行：用量标识 %q 已存在但内容不同（已有客户=%s 时间=%s 数量=%d）",
286						r.line, r.rec.ID, existing.CustomerID, existing.Time, existing.Quantity))
287					continue
288				}
289				dupCount++
290				continue
291			}
292	
293			// 全新标识：不得进入该客户已封账的 UTC 自然月。
294			month := r.t.UTC().Format("2006-01")
295			if s.sealed(r.rec.CustomerID, month) {
296				problems = append(problems, fmt.Sprintf("第 %d 行：客户 %s 的 %s 已封账，新用量 %q 不得进入",
297					r.line, r.rec.CustomerID, month, r.rec.ID))
298				continue
299			}
300	
301			rr := r
302			accepted[r.rec.ID] = rr
303			ordered = append(ordered, rr)
304			newCount++
305		}
306	
307		if len(problems) > 0 {
308			return fmt.Errorf("导入失败，整批未生效（共 %d 个问题）：\n  %s", len(problems), strings.Join(problems, "\n  "))
309		}
310	
311		for _, r := range ordered {
312			rec := r.rec
313			s.Usage[rec.ID] = &rec
314		}
315		if err := s.save(); err != nil {
316			return err
317		}
318		fmt.Fprintf(stdout, "导入完成（%s）：新增 %d 条，重复跳过 %d 条\n", source, newCount, dupCount)
319		return nil
320	}
321	
322	// parseUsageFile 完整读取 CSV，做格式层面的解析；业务层面的校验在调用方完成。
323	func parseUsageFile(r io.Reader) ([]*parsedRow, []string) {
324		cr := csv.NewReader(r)
325		cr.FieldsPerRecord = 4
326		cr.TrimLeadingSpace = true
327	
328		header, err := cr.Read()
329		if err == io.EOF {
330			return nil, []string{"文件为空：首行必须是表头 " + usageHeader}
331		}
332		if err != nil {
333			return nil, []string{fmt.Sprintf("无法读取表头：%v（首行必须是 %s）", err, usageHeader)}
334		}
335		for i := range header {
336			header[i] = strings.TrimSpace(header[i])
337		}
338		if len(header) != 4 || header[0] != "usage_id" || header[1] != "customer_id" ||
339			header[2] != "time" || header[3] != "quantity" {
340			return nil, []string{fmt.Sprintf("表头必须是 %s，实际为 %s", usageHeader, strings.Join(header, ","))}
341		}
342	
343		var rows []*parsedRow
344		var problems []string
345		line := 1
346		for {
347			rec, err := cr.Read()
348			if err == io.EOF {
349				break
350			}
351			line++
352			if err != nil {
353				problems = append(problems, fmt.Sprintf("第 %d 行：CSV 格式错误：%v", line, err))
354				if pe, ok := err.(*csv.ParseError); ok && pe.Err == csv.ErrFieldCount {
355					// 字段数错误后继续读取仍可能拿到错乱记录，直接终止解析。
356					break
357				}
358				continue
359			}
360			for i := range rec {
361				rec[i] = strings.TrimSpace(rec[i])
362			}
363	
364			id, custID, ts, qtyText := rec[0], rec[1], rec[2], rec[3]
365			if id == "" {
366				problems = append(problems, fmt.Sprintf("第 %d 行：用量标识不能为空", line))
367				continue
368			}
369			if custID == "" {
370				problems = append(problems, fmt.Sprintf("第 %d 行：客户标识不能为空", line))
371				continue
372			}
373			t, err := time.Parse(time.RFC3339, ts)
374			if err != nil {
375				problems = append(problems, fmt.Sprintf("第 %d 行：时间 %q 不是 RFC3339 格式：%v", line, ts, err))
376				continue
377			}
378			qty, err := strconv.ParseInt(qtyText, 10, 64)
379			if err != nil {
380				problems = append(problems, fmt.Sprintf("第 %d 行：数量 %q 不是有符号 64 位整数", line, qtyText))
381				continue
382			}
383			if qty <= 0 {
384				problems = append(problems, fmt.Sprintf("第 %d 行：数量必须是正整数，收到 %d", line, qty))
385				continue
386			}
387	
388			rows = append(rows, &parsedRow{
389				line: line,
390				rec:  usageRecord{ID: id, CustomerID: custID, Time: ts, Quantity: qty},
391				t:    t,
392			})
393		}
394		return rows, problems
395	}
