397	// sameUsage 按（客户、解析后的时间点、数量）判定两条记录内容是否相同，
398	// 时间比较的是瞬间，因此 Z 与 +08:00 表示同一时刻视为相同。
399	func sameUsage(existing *usageRecord, candidate *usageRecord, candidateT time.Time) bool {
400		if existing.CustomerID != candidate.CustomerID || existing.Quantity != candidate.Quantity {
401			return false
402		}
403		et, err := time.Parse(time.RFC3339, existing.Time)
404		if err != nil {
405			return existing.Time == candidate.Time
406		}
407		return et.Equal(candidateT)
408	}
