435	func cmdBillSettle(dir, customerID, month string) error {
436		if !validMonth(month) {
437			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
438		}
439		s, err := loadStore(dir)
440		if err != nil {
441			return err
442		}
443		cust, ok := s.Customers[customerID]
444		if !ok {
445			return fmt.Errorf("客户标识 %q 不存在", customerID)
446		}
447	
448		key := billKey(customerID, month)
449		if existing, ok := s.Bills[key]; ok {
450			// 幂等：同一客户同一月份重复结算，直接返回原账单，
451			// 不重新计费、不产生新账单或调整、不落盘。
452			fmt.Fprintf(stdout, "客户 %s 的 %s 已结算，返回原账单（幂等，不重新计费）：\n\n", customerID, month)
453			printBill(existing, cust, s)
454			return nil
455		}
456	
457		// 归集该客户 UTC 自然月内的全部用量，区间为左闭右开 [月初, 下月初)。
458		var inMonthRecs []*usageRecord
459		for _, u := range s.Usage {
460			if u.CustomerID == customerID && inMonth(u.Time, month) {
461				inMonthRecs = append(inMonthRecs, u)
462			}
463		}
464		if len(inMonthRecs) == 0 {
465			return fmt.Errorf("客户 %s 在 %s 没有用量，拒绝结算且不封账", customerID, month)
466		}
467		sortByInstant(inMonthRecs)
468	
469		// 绑定阶梯方案的客户走按月累计分档计价；固定单价客户保持原路径。
470		if cust.PlanID != "" {
471			return settleTiered(s, cust, month, inMonthRecs)
472		}
473	
474		lines := make([]billLine, 0, len(inMonthRecs))
475		var totalQty, totalFee int64
476		for _, u := range inMonthRecs {
477			lineFee, err := mul64(u.Quantity, cust.Price)
478			if err != nil {
479				return fmt.Errorf("用量 %s：数量 %d × 单价 %d 金额溢出，拒绝结算且不封账", u.ID, u.Quantity, cust.Price)
480			}
481			totalQty, err = add64(totalQty, u.Quantity)
482			if err != nil {
483				return fmt.Errorf("汇总数量溢出有符号 64 位整数范围，拒绝结算且不封账")
484			}
485			totalFee, err = add64(totalFee, lineFee)
486			if err != nil {
487				return fmt.Errorf("汇总金额溢出有符号 64 位整数范围，拒绝结算且不封账")
488			}
489			lines = append(lines, billLine{
490				UsageID:  u.ID,
491				Time:     u.Time,
492				Quantity: u.Quantity,
493				LineFee:  lineFee,
494			})
495		}
496	
497		b := &bill{
498			ID:         stableBillID(customerID, month),
499			CustomerID: customerID,
500			Month:      month,
501			TotalQty:   totalQty,
502			UnitPrice:  cust.Price,
503			TotalFee:   totalFee,
504			Lines:      lines,
505			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
506		}
507		s.Bills[key] = b
508	
509		// 账单与封账状态在同一次原子保存中一起持久化；保存失败则一切不生效。
510		if err := s.save(); err != nil {
511			delete(s.Bills, key)
512			return err
513		}
514		fmt.Fprintf(stdout, "结算完成，客户 %s 的 %s 已封账：\n\n", customerID, month)
515		printBill(b, cust, s)
516		return nil
517	}
