539	func sortByInstant(us []*usageRecord) {
540		// 入参时间均已在载入/导入时校验为 RFC3339。
541		sort.Slice(us, func(i, j int) bool {
542			ti, _ := time.Parse(time.RFC3339, us[i].Time)
543			tj, _ := time.Parse(time.RFC3339, us[j].Time)
544			ui, uj := ti.UTC(), tj.UTC()
545			if !ui.Equal(uj) {
546				return ui.Before(uj)
547			}
548			return us[i].ID < us[j].ID
549		})
550	}
