558	func printBill(b *bill, cust *customer, s *state) {
559		adjs := adjustmentsFor(s, b.CustomerID, b.Month)
560		// 收款历史保留所有曾涉及本账单的收款：首次登记或任一次更正分配
561		// 涉及该月即纳入，即使后来被更正移出。
562		pays := paymentsEverFor(s, b.CustomerID, b.Month)
563		fmt.Fprintf(stdout, "账单标识：%s\n", b.ID)
564		fmt.Fprintf(stdout, "客户：%s（%s）\n", cust.ID, cust.Name)
565		fmt.Fprintf(stdout, "月份：%s（UTC 自然月，左闭右开）\n", b.Month)
566		tiered := b.Pricing == "tiered"
567		if tiered {
568			// 阶梯账单明确计价类型并展示方案与完整规则，不伪造统一单价。
569			fmt.Fprintf(stdout, "计价类型：阶梯计费（按 UTC 自然月累计用量分档计价，每月从零累计）\n")
570			fmt.Fprintf(stdout, "方案：%s（%s）\n", b.PlanID, b.PlanName)
571			fmt.Fprintln(stdout, "阶梯规则：")
572			for i, t := range b.PlanTiers {
573				if t.Limit == 0 {
574					fmt.Fprintf(stdout, "  第 %d 档：累计数量无上限，单价 %d 分（%s）\n", i+1, t.Price, moneyFen(t.Price))
575				} else {
576					fmt.Fprintf(stdout, "  第 %d 档：累计上限 %d，单价 %d 分（%s）\n", i+1, t.Limit, t.Price, moneyFen(t.Price))
577				}
578			}
579		} else {
580			fmt.Fprintf(stdout, "单价：%d 分（%s）\n", b.UnitPrice, moneyFen(b.UnitPrice))
581		}
582		fmt.Fprintf(stdout, "总数量：%d\n", b.TotalQty)
583		fmt.Fprintf(stdout, "总金额：%d 分（%s）\n", b.TotalFee, moneyFen(b.TotalFee))
584		if tiered {
585			fmt.Fprintln(stdout, "各档合计：")
586			for i, tt := range b.TierTotals {
587				fmt.Fprintf(stdout, "  第 %d 档：数量 %d，单价 %d 分，金额 %d 分（%s）\n",
588					i+1, tt.Quantity, b.PlanTiers[i].Price, tt.Fee, moneyFen(tt.Fee))
589			}
590		}
591		// 数据在载入时已校验一致，此处计算不会出错。
592		net, payable, _ := billTotals(b, adjs)
593		received, _ := paymentReceived(s, b.CustomerID, b.Month)
594		outstanding := payable - received // 不变量保证 0 ≤ 实收 ≤ 当前应付
595		fmt.Fprintf(stdout, "调整净额：%+d 分（%s）\n", net, moneyFen(net))
596		fmt.Fprintf(stdout, "当前应付：%d 分（%s）\n", payable, moneyFen(payable))
597		fmt.Fprintf(stdout, "实收：%d 分（%s）\n", received, moneyFen(received))
598		fmt.Fprintf(stdout, "未收余额：%d 分（%s）\n", outstanding, moneyFen(outstanding))
599		fmt.Fprintln(stdout, "明细：")
600		for i, ln := range b.Lines {
601			fmt.Fprintf(stdout, "  %d. 用量标识=%s 时间=%s 数量=%d 小计=%d 分（%s）\n",
602				i+1, ln.UsageID, ln.Time, ln.Quantity, ln.LineFee, moneyFen(ln.LineFee))
603			// 阶梯账单逐条展示跨档分段的数量、单价与小计。
604			for j, seg := range ln.Segments {
605				fmt.Fprintf(stdout, "     分段 %d：第 %d 档 数量=%d 单价=%d 分 小计=%d 分（%s）\n",
606					j+1, seg.Tier+1, seg.Quantity, b.PlanTiers[seg.Tier].Price, seg.Fee, moneyFen(seg.Fee))
607			}
608		}
609		if len(adjs) == 0 {
610			fmt.Fprintln(stdout, "调整与撤销历史：无")
611		} else {
612			fmt.Fprintln(stdout, "调整与撤销历史（按成功操作顺序）：")
613			for i, ev := range historyEvents(adjs) {
614				fmt.Fprintf(stdout, "  %d. %s\n", i+1, ev)
615			}
616		}
617		if len(pays) == 0 {
618			fmt.Fprintln(stdout, "收款与撤销历史：无")
619		} else {
620			fmt.Fprintln(stdout, "收款与撤销历史（按成功操作顺序）：")
621			for i, ev := range paymentHistoryEvents(s, pays, b.Month) {
622				fmt.Fprintf(stdout, "  %d. %s\n", i+1, ev)
623			}
624		}
625	}
