710	// parseAmount 解析调整金额：有符号 64 位整数、非零（正数补收、负数减免）。
711	func parseAmount(text string) (int64, error) {
712		text = strings.TrimSpace(text)
713		amount, err := strconv.ParseInt(text, 10, 64)
714		if err != nil {
715			return 0, fmt.Errorf("调整金额 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
716		}
717		if amount == 0 {
718			return 0, fmt.Errorf("调整金额不能为零分（正数补收、负数减免）")
719		}
720		return amount, nil
721	}
722	
723	func cmdBillAdjust(dir, customerID, month, adjID, amountText, reason string) error {
724		if !validMonth(month) {
725			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
726		}
727		if strings.TrimSpace(adjID) == "" {
728			return fmt.Errorf("调整标识不能为空")
729		}
730		amount, err := parseAmount(amountText)
731		if err != nil {
732			return err
733		}
734		if strings.TrimSpace(reason) == "" {
735			return fmt.Errorf("调整原因不能为空")
736		}
737	
738		s, err := loadStore(dir)
739		if err != nil {
740			return err
741		}
742		if _, ok := s.Customers[customerID]; !ok {
743			return fmt.Errorf("客户标识 %q 不存在", customerID)
744		}
745		b, ok := s.Bills[billKey(customerID, month)]
746		if !ok {
747			return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），费用调整只能作用于已存在账单", customerID, month)
748		}
749	
750		if existing, ok := s.Adjustments[adjID]; ok {
751			// 相同标识按客户、月份、金额、原因判断重复：内容相同返回已保存
752			// 记录，不再次增减应付；已撤销的重放仍返回已撤销状态，不重新生效。
753			if existing.CustomerID == customerID && existing.Month == month &&
754				existing.Amount == amount && existing.Reason == reason {
755				fmt.Fprintf(stdout, "调整 %q 已存在且内容相同，返回已保存记录（不重复增减应付）：\n\n", adjID)
756				printAdjustment(existing, s)
757				return nil
758			}
759			return fmt.Errorf("调整标识 %q 已存在但内容不同（已有：客户=%s 月份=%s 金额=%d 原因=%q），拒绝复用",
760				adjID, existing.CustomerID, existing.Month, existing.Amount, existing.Reason)
761		}
762	
763		// 应付可行性预检：原总金额 + 全部未撤销调整 + 本次金额必须落在
764		// [0, 有符号 64 位最大值] 内，且不得低于已登记实收，否则拒绝且
765		// 不占用该调整标识。
766		_, payable, err := billTotals(b, adjustmentsFor(s, customerID, month))
767		if err != nil {
768			return fmt.Errorf("账单当前应付异常，拒绝调整: %w", err)
769		}
770		received, err := paymentReceived(s, customerID, month)
771		if err != nil {
772			return fmt.Errorf("实收累计异常，拒绝调整: %w", err)
773		}
774		newPayable, err := addSigned64(payable, amount)
775		if err != nil {
776			return fmt.Errorf("调整后当前应付超出有符号 64 位最大值（当前 %d 分，本次 %+d 分），拒绝调整", payable, amount)
777		}
778		if newPayable < 0 {
779			return fmt.Errorf("调整后当前应付将为 %d 分（小于 0，当前 %d 分，本次 %+d 分），拒绝调整", newPayable, payable, amount)
780		}
781		if newPayable < received {
782			return fmt.Errorf("调整后当前应付 %d 分将低于实收 %d 分（当前 %d 分，本次 %+d 分），拒绝调整；可先撤销误登记的收款再重试",
783				newPayable, received, payable, amount)
784		}
785	
786		a := &adjustment{
