907	// parsePositiveAmount 解析收款金额：正整数分（不接受零、负数、小数）。
908	func parsePositiveAmount(text string) (int64, error) {
909		text = strings.TrimSpace(text)
910		amount, err := strconv.ParseInt(text, 10, 64)
911		if err != nil {
912			return 0, fmt.Errorf("收款金额 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
913		}
914		if amount <= 0 {
915			return 0, fmt.Errorf("收款金额必须是正整数分，收到 %d", amount)
916		}
917		return amount, nil
918	}
