1079	// sameAllocations 判定两个分配列表的月份-金额对应关系相同（顺序无关）。
1080	func sameAllocations(a, b []paymentAllocation) bool {
1081		if len(a) != len(b) {
1082			return false
1083		}
1084		for _, al := range b {
1085			if allocAmountFor(a, al.Month) != al.Amount {
1086				return false
1087			}
1088		}
1089		return true
1090	}
1091	
1092	// formatAllocations 以 "2026-09:500,2026-10:300" 形式展示分配列表。
1093	func formatAllocations(allocs []paymentAllocation) string {
1094		parts := make([]string, len(allocs))
1095		for i, al := range allocs {
1096			parts[i] = fmt.Sprintf("%s:%d", al.Month, al.Amount)
1097		}
1098		return strings.Join(parts, ",")
1099	}
