1165	// printPayment 输出单笔收款记录：总额、首次登记的全部分配（永久保留，
1166	// 判重依据）与当前状态；经历过更正时同时展示当前生效的最新分配。
1167	// 各月应付/实收取自当前库状态。
1168	func printPayment(p *payment, s *state) {
1169		fmt.Fprintf(stdout, "收款标识：%s\n", p.ID)
1170		fmt.Fprintf(stdout, "客户：%s\n", p.CustomerID)
1171		fmt.Fprintf(stdout, "收款总额：%d 分（%s）\n", p.Total, moneyFen(p.Total))
1172		fmt.Fprintf(stdout, "备注：%s\n", p.Note)
1173		if p.Revoked {
1174			fmt.Fprintf(stdout, "当前状态：已撤销（撤销原因：%s）\n", p.RevokeReason)
1175		} else {
1176			fmt.Fprintf(stdout, "当前状态：实收中\n")
1177		}
1178		fmt.Fprintln(stdout, "分配明细（首次登记，永久保留）：")
1179		for i, al := range p.Allocations {
1180			b := s.Bills[billKey(p.CustomerID, al.Month)] // 载入时已校验存在
1181			_, payable, _ := billTotals(b, adjustmentsFor(s, p.CustomerID, al.Month))
1182			received, _ := paymentReceived(s, p.CustomerID, al.Month)
1183			fmt.Fprintf(stdout, "  %d. 月份 %s：分配 %d 分（%s）；当前应付 %d 分，实收合计 %d 分，未收余额 %d 分\n",
1184				i+1, al.Month, al.Amount, moneyFen(al.Amount), payable, received, payable-received)
1185		}
1186		if corrs := correctionsFor(s, p.ID); len(corrs) > 0 {
1187			fmt.Fprintf(stdout, "当前分配（经 %d 次更正，以最新为准）：%s\n",
1188				len(corrs), formatAllocations(currentAllocations(s, p)))
1189		}
1190	}
