1337	// printCorrection 输出单笔更正记录：关联收款、标识、原因、完整前后分配，
1338	// 以及前后分配涉及月份的当前余额。
1339	func printCorrection(c *correction, s *state) {
1340		p := s.Payments[c.PaymentID] // 载入时已校验存在
1341		before := allocationBefore(s, c)
1342		fmt.Fprintf(stdout, "更正标识：%s\n", c.ID)
1343		fmt.Fprintf(stdout, "关联收款：%s（客户 %s，总额 %d 分（%s），备注：%s）\n",
1344			p.ID, p.CustomerID, p.Total, moneyFen(p.Total), p.Note)
1345		fmt.Fprintf(stdout, "原因：%s\n", c.Reason)
1346		fmt.Fprintf(stdout, "更正前分配：%s\n", formatAllocations(before))
1347		fmt.Fprintf(stdout, "更正后分配：%s\n", formatAllocations(c.Allocations))
1348		fmt.Fprintln(stdout, "涉及月份当前余额：")
1349		for _, m := range unionMonths(before, c.Allocations) {
1350			b := s.Bills[billKey(p.CustomerID, m)] // 载入时已校验存在
1351			_, payable, _ := billTotals(b, adjustmentsFor(s, p.CustomerID, m))
1352			received, _ := paymentReceived(s, p.CustomerID, m)
1353			fmt.Fprintf(stdout, "  月份 %s：本笔分配 %d 分 → %d 分；当前应付 %d 分（%s），实收 %d 分（%s），未收余额 %d 分（%s）\n",
1354				m, allocAmountFor(before, m), allocAmountFor(c.Allocations, m),
1355				payable, moneyFen(payable), received, moneyFen(received), payable-received, moneyFen(payable-received))
1356		}
1357	}
