263	// validate 对读入的库做一致性检查，任何异常都按损坏处理。
264	func (s *state) validate() error {
265		if s.Version != stateVersion {
266			return fmt.Errorf("不支持的数据版本 %d（仅支持 %d）", s.Version, stateVersion)
267		}
268		if s.Customers == nil || s.Usage == nil || s.Bills == nil {
269			return errors.New("缺少必要的数据节")
270		}
271		for id, p := range s.Plans {
272			if p == nil {
273				return fmt.Errorf("方案 %q 的数据为空", id)
274			}
275			if p.ID != id {
276				return fmt.Errorf("方案标识不一致: 键 %q / 记录 %q", id, p.ID)
277			}
278			if err := validatePlanRules(p); err != nil {
279				return err
280			}
281		}
282		for id, c := range s.Customers {
283			if c == nil {
284				return fmt.Errorf("客户 %q 的数据为空", id)
285			}
286			if c.ID != id {
287				return fmt.Errorf("客户标识不一致: 键 %q / 记录 %q", id, c.ID)
288			}
289			if c.ID == "" || c.Name == "" {
290				return fmt.Errorf("客户 %q 的标识或名称为空", id)
291			}
292			if c.Price < 0 {
293				return fmt.Errorf("客户 %q 单价为负", id)
294			}
295			if c.PlanID != "" {
296				if _, ok := s.Plans[c.PlanID]; !ok {
297					return fmt.Errorf("客户 %q 绑定了不存在的方案 %q", id, c.PlanID)
298				}
299			}
300		}
301		// 方案变更：键、客户（须为绑定阶梯方案的客户）、目标方案、生效月与
302		// 原因都必须自洽；同一客户的变更生效月由键保证唯一。
303		for key, ch := range s.PlanChanges {
304			if ch == nil {
305				return fmt.Errorf("方案变更 %q 的数据为空", key)
306			}
307			if planChangeKey(ch.CustomerID, ch.Month) != key {
308				return fmt.Errorf("方案变更键不一致: 键 %q / 客户月份 %s|%s", key, ch.CustomerID, ch.Month)
309			}
310			c, ok := s.Customers[ch.CustomerID]
311			if !ok {
312				return fmt.Errorf("方案变更 %q 引用了不存在的客户 %q", key, ch.CustomerID)
313			}
314			if c.PlanID == "" {
315				return fmt.Errorf("方案变更 %q 的客户 %q 未绑定阶梯方案", key, ch.CustomerID)
316			}
317			if !validMonth(ch.Month) {
318				return fmt.Errorf("方案变更 %q 的生效月无效", key)
319			}
320			if _, ok := s.Plans[ch.PlanID]; !ok {
321				return fmt.Errorf("方案变更 %q 引用了不存在的方案 %q", key, ch.PlanID)
322			}
323			if strings.TrimSpace(ch.Reason) == "" {
324				return fmt.Errorf("方案变更 %q 的原因为空", key)
325			}
326		}
327		for id, u := range s.Usage {
328			if u == nil {
329				return fmt.Errorf("用量 %q 的数据为空", id)
330			}
331			if u.ID != id {
332				return fmt.Errorf("用量标识不一致: 键 %q / 记录 %q", id, u.ID)
333			}
334			if u.ID == "" {
335				return errors.New("存在空的用量标识")
336			}
337			if _, ok := s.Customers[u.CustomerID]; !ok {
338				return fmt.Errorf("用量 %q 引用了不存在的客户 %q", u.ID, u.CustomerID)
339			}
340			if u.Quantity <= 0 {
341				return fmt.Errorf("用量 %q 的数量非正", u.ID)
342			}
343			if _, err := time.Parse(time.RFC3339, u.Time); err != nil {
344				return fmt.Errorf("用量 %q 的时间不是 RFC3339: %w", u.ID, err)
345			}
346		}
347		for key, b := range s.Bills {
348			if b == nil {
349				return fmt.Errorf("账单 %q 的数据为空", key)
350			}
351			if billKey(b.CustomerID, b.Month) != key {
352				return fmt.Errorf("账单键不一致: 键 %q / 客户月份 %s|%s", key, b.CustomerID, b.Month)
353			}
354			if _, ok := s.Customers[b.CustomerID]; !ok {
355				return fmt.Errorf("账单 %q 引用了不存在的客户 %q", key, b.CustomerID)
356			}
357			if !validMonth(b.Month) {
358				return fmt.Errorf("账单 %q 的月份无效", key)
359			}
360			if len(b.Lines) == 0 {
361				return fmt.Errorf("账单 %q 没有明细", key)
362			}
363			var qty, fee int64
364			for _, ln := range b.Lines {
365				u, ok := s.Usage[ln.UsageID]
366				if !ok {
367					return fmt.Errorf("账单 %q 引用了不存在的用量 %q", key, ln.UsageID)
368				}
369				if u.CustomerID != b.CustomerID || u.Time != ln.Time || u.Quantity != ln.Quantity {
370					return fmt.Errorf("账单 %q 的明细 %q 与用量记录不一致", key, ln.UsageID)
371				}
372				if !inMonth(u.Time, b.Month) {
373					return fmt.Errorf("账单 %q 的明细 %q 不在账期内", key, ln.UsageID)
374				}
375				var err error
376				qty, err = add64(qty, ln.Quantity)
377				if err != nil {
378					return fmt.Errorf("账单 %q 汇总数量溢出", key)
379				}
380				fee, err = add64(fee, ln.LineFee)
381				if err != nil {
382					return fmt.Errorf("账单 %q 汇总金额溢出", key)
383				}
384			}
385			if qty != b.TotalQty {
386				return fmt.Errorf("账单 %q 总数量与明细不符", key)
387			}
388			if fee != b.TotalFee {
389				return fmt.Errorf("账单 %q 总金额与明细不符", key)
390			}
391			c := s.Customers[b.CustomerID]
392			switch b.Pricing {
393			case "", "fixed":
394				// 固定单价账单：每条小计必须等于 数量×客户固定单价，且不得
395				// 携带阶梯方案信息或分段。
396				if b.PlanID != "" || b.PlanName != "" || len(b.PlanTiers) > 0 || len(b.TierTotals) > 0 {
397					return fmt.Errorf("账单 %q 是固定单价账单但携带阶梯方案信息", key)
398				}
399				for _, ln := range b.Lines {
400					if len(ln.Segments) > 0 {
401						return fmt.Errorf("账单 %q 的明细 %q 携带阶梯分段", key, ln.UsageID)
402					}
403					lf, err := mul64(ln.Quantity, c.Price)
404					if err != nil {
405						return fmt.Errorf("账单 %q 明细 %q 小计溢出", key, ln.UsageID)
406					}
407					if lf != ln.LineFee {
408						return fmt.Errorf("账单 %q 明细 %q 小计与数量×单价不符", key, ln.UsageID)
409					}
410				}
411				if b.UnitPrice != c.Price {
412					return fmt.Errorf("账单 %q 单价与客户固定单价不符", key)
413				}
414			case "tiered":
415				if err := s.validateTieredBill(key, b, c); err != nil {
416					return err
417				}
418			default:
419				return fmt.Errorf("账单 %q 的计价类型 %q 未知", key, b.Pricing)
420			}
421			// 封账期内不得存在游离于账单之外的用量（封账后新增被禁止，
422			// 而已入账记录理应全部在明细中）。
423			for _, u := range s.Usage {
424				if u.CustomerID == b.CustomerID && inMonth(u.Time, b.Month) {
425					found := false
426					for _, ln := range b.Lines {
427						if ln.UsageID == u.ID {
428							found = true
429							break
430						}
431					}
432					if !found {
433						return fmt.Errorf("客户 %s 的 %s 已封账，但用量 %q 未计入账单", b.CustomerID, b.Month, u.ID)
434					}
435				}
436			}
437		}
438	
439		// 调整与收款记录：标识、内容、引用与序号都必须自洽。
440		// 调整与收款共用同一个全局操作序号池；两者标识命名空间相互独立，
441		// 允许同名，各自判重与撤销。
442		if s.NextSeq < 0 {
443			return fmt.Errorf("操作序号计数器为负: %d", s.NextSeq)
444		}
445		seenSeq := make(map[int64]string) // 全局操作序号（登记与撤销共用同一池）-> 来源描述
446		for id, a := range s.Adjustments {
447			if a == nil {
448				return fmt.Errorf("调整 %q 的数据为空", id)
449			}
450			if a.ID != id {
451				return fmt.Errorf("调整标识不一致: 键 %q / 记录 %q", id, a.ID)
452			}
453			if a.ID == "" {
454				return errors.New("存在空的调整标识")
455			}
456			if a.Amount == 0 {
457				return fmt.Errorf("调整 %q 的金额为零", id)
458			}
459			if strings.TrimSpace(a.Reason) == "" {
460				return fmt.Errorf("调整 %q 的原因为空", id)
461			}
462			if !validMonth(a.Month) {
463				return fmt.Errorf("调整 %q 的月份无效", id)
464			}
465			if _, ok := s.Customers[a.CustomerID]; !ok {
466				return fmt.Errorf("调整 %q 引用了不存在的客户 %q", id, a.CustomerID)
467			}
468			if _, ok := s.Bills[billKey(a.CustomerID, a.Month)]; !ok {
469				return fmt.Errorf("调整 %q 引用了不存在的账单（客户 %s 月份 %s）", id, a.CustomerID, a.Month)
470			}
471			if a.Seq < 1 || a.Seq > s.NextSeq {
472				return fmt.Errorf("调整 %q 的操作序号越界", id)
473			}
474			if prev, dup := seenSeq[a.Seq]; dup {
475				return fmt.Errorf("调整 %q 与 %q 的操作序号重复", id, prev)
476			}
477			seenSeq[a.Seq] = "调整 " + id
478			if a.Revoked {
479				if strings.TrimSpace(a.RevokeReason) == "" {
480					return fmt.Errorf("调整 %q 已撤销但撤销原因为空", id)
481				}
482				if a.RevokeSeq <= a.Seq || a.RevokeSeq > s.NextSeq {
483					return fmt.Errorf("调整 %q 的撤销序号越界", id)
484				}
485				if prev, dup := seenSeq[a.RevokeSeq]; dup {
486					return fmt.Errorf("撤销调整 %q 与 %q 的操作序号重复", id, prev)
487				}
488				seenSeq[a.RevokeSeq] = "撤销调整 " + id
489			} else if a.RevokeReason != "" || a.RevokeSeq != 0 {
490				return fmt.Errorf("调整 %q 未撤销但存在撤销信息", id)
491			}
492		}
493		for id, p := range s.Payments {
494			if p == nil {
495				return fmt.Errorf("收款 %q 的数据为空", id)
496			}
497			if p.ID != id {
498				return fmt.Errorf("收款标识不一致: 键 %q / 记录 %q", id, p.ID)
499			}
500			if p.ID == "" {
501				return errors.New("存在空的收款标识")
502			}
503			if p.Total <= 0 {
504				return fmt.Errorf("收款 %q 的总额不是正整数", id)
505			}
506			if strings.TrimSpace(p.Note) == "" {
507				return fmt.Errorf("收款 %q 的备注为空", id)
508			}
509			if _, ok := s.Customers[p.CustomerID]; !ok {
510				return fmt.Errorf("收款 %q 引用了不存在的客户 %q", id, p.CustomerID)
511			}
512			if len(p.Allocations) == 0 {
513				return fmt.Errorf("收款 %q 没有分配", id)
514			}
515			seenMonths := make(map[string]bool)
516			var sum int64
517			for _, al := range p.Allocations {
518				if !validMonth(al.Month) {
519					return fmt.Errorf("收款 %q 的分配月份 %q 无效", id, al.Month)
520				}
521				if seenMonths[al.Month] {
522					return fmt.Errorf("收款 %q 的分配月份 %s 重复", id, al.Month)
523				}
524				seenMonths[al.Month] = true
525				if al.Amount <= 0 {
526					return fmt.Errorf("收款 %q 在 %s 的分配金额不是正整数", id, al.Month)
527				}
528				if _, ok := s.Bills[billKey(p.CustomerID, al.Month)]; !ok {
529					return fmt.Errorf("收款 %q 的分配引用了不存在的账单（客户 %s 月份 %s）", id, p.CustomerID, al.Month)
530				}
531				var err error
532				sum, err = add64(sum, al.Amount)
533				if err != nil {
534					return fmt.Errorf("收款 %q 的分配金额汇总溢出: %w", id, err)
535				}
536			}
537			if sum != p.Total {
538				return fmt.Errorf("收款 %q 的分配合计 %d 分与总额 %d 分不一致", id, sum, p.Total)
539			}
540			if p.Seq < 1 || p.Seq > s.NextSeq {
541				return fmt.Errorf("收款 %q 的操作序号越界", id)
542			}
543			if prev, dup := seenSeq[p.Seq]; dup {
544				return fmt.Errorf("收款 %q 与 %q 的操作序号重复", id, prev)
545			}
546			seenSeq[p.Seq] = "收款 " + id
547			if p.Revoked {
548				if strings.TrimSpace(p.RevokeReason) == "" {
549					return fmt.Errorf("收款 %q 已撤销但撤销原因为空", id)
550				}
551				if p.RevokeSeq <= p.Seq || p.RevokeSeq > s.NextSeq {
552					return fmt.Errorf("收款 %q 的撤销序号越界", id)
553				}
554				if prev, dup := seenSeq[p.RevokeSeq]; dup {
555					return fmt.Errorf("撤销收款 %q 与 %q 的操作序号重复", id, prev)
556				}
557				seenSeq[p.RevokeSeq] = "撤销收款 " + id
558			} else if p.RevokeReason != "" || p.RevokeSeq != 0 {
559				return fmt.Errorf("收款 %q 未撤销但存在撤销信息", id)
560			}
561		}
562		// 分配更正记录：标识、目标收款、原因、新分配与序号都必须自洽。
563		// 更正标识与收款、调整标识命名空间相互独立，允许同名。
564		for id, c := range s.Corrections {
565			if c == nil {
566				return fmt.Errorf("更正 %q 的数据为空", id)
567			}
568			if c.ID != id {
569				return fmt.Errorf("更正标识不一致: 键 %q / 记录 %q", id, c.ID)
570			}
571			if c.ID == "" {
572				return errors.New("存在空的更正标识")
573			}
574			p, ok := s.Payments[c.PaymentID]
575			if !ok {
576				return fmt.Errorf("更正 %q 引用了不存在的收款 %q", id, c.PaymentID)
577			}
578			if strings.TrimSpace(c.Reason) == "" {
579				return fmt.Errorf("更正 %q 的原因为空", id)
580			}
581			if len(c.Allocations) == 0 {
582				return fmt.Errorf("更正 %q 没有新分配", id)
583			}
584			seenMonths := make(map[string]bool)
585			var sum int64
586			for _, al := range c.Allocations {
587				if !validMonth(al.Month) {
588					return fmt.Errorf("更正 %q 的分配月份 %q 无效", id, al.Month)
589				}
590				if seenMonths[al.Month] {
591					return fmt.Errorf("更正 %q 的分配月份 %s 重复", id, al.Month)
592				}
593				seenMonths[al.Month] = true
594				if al.Amount <= 0 {
595					return fmt.Errorf("更正 %q 在 %s 的分配金额不是正整数", id, al.Month)
596				}
597				if _, ok := s.Bills[billKey(p.CustomerID, al.Month)]; !ok {
598					return fmt.Errorf("更正 %q 的分配引用了不存在的账单（客户 %s 月份 %s）", id, p.CustomerID, al.Month)
599				}
600				var err error
601				sum, err = add64(sum, al.Amount)
602				if err != nil {
603					return fmt.Errorf("更正 %q 的分配金额汇总溢出: %w", id, err)
604				}
605			}
606			if sum != p.Total {
607				return fmt.Errorf("更正 %q 的分配合计 %d 分与关联收款 %q 的总额 %d 分不一致", id, sum, c.PaymentID, p.Total)
608			}
609			if c.Seq <= p.Seq || c.Seq > s.NextSeq {
610				return fmt.Errorf("更正 %q 的操作序号越界", id)
611			}
612			if p.Revoked && c.Seq > p.RevokeSeq {
613				return fmt.Errorf("更正 %q 的操作序号晚于关联收款 %q 的撤销序号", id, c.PaymentID)
614			}
615			if prev, dup := seenSeq[c.Seq]; dup {
616				return fmt.Errorf("更正 %q 与 %q 的操作序号重复", id, prev)
617			}
618			seenSeq[c.Seq] = "更正 " + id
619		}
620		// 每张账单：当前应付（原总金额 + 全部未撤销调整净额）必须介于
621		// 0 与有符号 64 位最大值之间；实收（全部未撤销收款按最新分配在该月
622		// 计入之和）必须满足 0 ≤ 实收 ≤ 当前应付。越界说明金额与记录不一致。
623		for key, b := range s.Bills {
624			_, payable, err := billTotals(b, adjustmentsFor(s, b.CustomerID, b.Month))
625			if err != nil {
626				return fmt.Errorf("账单 %q 的调整金额与记录不一致: %w", key, err)
627			}
628			received, err := paymentReceived(s, b.CustomerID, b.Month)
629			if err != nil {
630				return fmt.Errorf("账单 %q 的收款金额与记录不一致: %w", key, err)
631			}
632			if received > payable {
633				return fmt.Errorf("账单 %q 的实收 %d 分超过当前应付 %d 分", key, received, payable)
634			}
635		}
636		return nil
637	}
638	
639	// validatePlanRules 校验阶梯方案的标识、名称与阶梯规则本身自洽：
640	// 至少一档，有限上限为严格递增的正整数，最后一档无上限，单价非负。
641	func validatePlanRules(p *plan) error {
642		if p.ID == "" || p.Name == "" {
643			return fmt.Errorf("方案 %q 的标识或名称为空", p.ID)
644		}
645		if len(p.Tiers) == 0 {
646			return fmt.Errorf("方案 %q 至少需要一档阶梯", p.ID)
647		}
648		prev := int64(0)
649		for i, t := range p.Tiers {
650			if t.Price < 0 {
651				return fmt.Errorf("方案 %q 第 %d 档单价为负", p.ID, i+1)
652			}
653			if i == len(p.Tiers)-1 {
654				if t.Limit != 0 {
655					return fmt.Errorf("方案 %q 最后一档必须无上限", p.ID)
656				}
657			} else {
658				if t.Limit <= 0 {
659					return fmt.Errorf("方案 %q 第 %d 档上限必须是正整数", p.ID, i+1)
660				}
661				if t.Limit <= prev {
662					return fmt.Errorf("方案 %q 的有限上限必须严格递增", p.ID)
663				}
664				prev = t.Limit
665			}
666		}
667		return nil
668	}
669	
670	// tiersEqual 判定两份阶梯规则完全相同。
671	func tiersEqual(a, b []tier) bool {
672		if len(a) != len(b) {
673			return false
674		}
675		for i := range a {
676			if a[i] != b[i] {
677				return false
678			}
679		}
680		return true
681	}
682	
683	// segmentsEqual 判定两份分段列表完全相同。
684	func segmentsEqual(a, b []lineSegment) bool {
685		if len(a) != len(b) {
686			return false
687		}
688		for i := range a {
689			if a[i] != b[i] {
690				return false
691			}
692		}
693		return true
694	}
695	
696	// sortedByInstant 判定用量记录是否按（解析后的时间点升序、同一时间按
697	// 标识字典序）排列，即阶梯计价的计价顺序。
698	func sortedByInstant(recs []*usageRecord) bool {
699		for i := 1; i < len(recs); i++ {
700			ti, _ := time.Parse(time.RFC3339, recs[i-1].Time)
701			tj, _ := time.Parse(time.RFC3339, recs[i].Time)
702			ui, uj := ti.UTC(), tj.UTC()
703			if uj.Before(ui) || (uj.Equal(ui) && recs[i].ID <= recs[i-1].ID) {
704				return false
705			}
706		}
707		return true
708	}
709	
710	// validateTieredBill 校验阶梯账单：方案引用有效、快照与方案一致、账单方案
711	// 符合账期月的方案安排，并按保存的方案规则从零累计重放计价，逐条比对分段、
712	// 小计、各档合计与总金额；任何不符都视为数据损坏。
713	func (s *state) validateTieredBill(key string, b *bill, c *customer) error {
714		if b.PlanID == "" {
715			return fmt.Errorf("账单 %q 缺少方案标识", key)
716		}
717		p, ok := s.Plans[b.PlanID]
718		if !ok {
719			return fmt.Errorf("账单 %q 引用了不存在的方案 %q", key, b.PlanID)
720		}
721		if b.PlanName != p.Name {
722			return fmt.Errorf("账单 %q 的方案名称快照与方案 %q 不符", key, b.PlanID)
723		}
724		if !tiersEqual(b.PlanTiers, p.Tiers) {
725			return fmt.Errorf("账单 %q 的方案规则快照与方案 %q 不符", key, b.PlanID)
726		}
727		// 账单方案必须符合账期安排：创建时绑定的初始方案被生效月不晚于
728		// 账期月的最后一次变更替换（无变更时即初始绑定，兼容旧存档）。
729		if want := s.effectivePlanID(c, b.Month); want != b.PlanID {
730			return fmt.Errorf("账单 %q 的方案 %q 与账期 %s 安排的方案 %q 不一致", key, b.PlanID, b.Month, want)
731		}
732		if b.UnitPrice != 0 {
733			return fmt.Errorf("账单 %q 是阶梯账单但保存了统一单价", key)
734		}
735		if len(b.TierTotals) != len(p.Tiers) {
736			return fmt.Errorf("账单 %q 的分档合计档数与方案规则不符", key)
737		}
738		// 明细必须按计价顺序排列（前面已逐条核验与用量记录一致）。
739		recs := make([]*usageRecord, len(b.Lines))
740		for i, ln := range b.Lines {
741			recs[i] = s.Usage[ln.UsageID]
742		}
743		if !sortedByInstant(recs) {
744			return fmt.Errorf("账单 %q 的明细未按计价顺序（时间点升序、同一时间按标识字典序）排列", key)
745		}
746		priced, err := tieredPrice(p.Tiers, recs)
747		if err != nil {
748			return fmt.Errorf("账单 %q 按方案规则计价失败: %w", key, err)
749		}
750		for i, ln := range b.Lines {
751			if !segmentsEqual(ln.Segments, priced.lines[i].segments) {
752				return fmt.Errorf("账单 %q 的明细 %q 分段与计价规则不符", key, ln.UsageID)
753			}
754			if ln.LineFee != priced.lines[i].fee {
755				return fmt.Errorf("账单 %q 的明细 %q 小计与计价规则不符", key, ln.UsageID)
756			}
757		}
758		for i, tt := range b.TierTotals {
759			if tt.Quantity != priced.tierQty[i] || tt.Fee != priced.tierFee[i] {
760				return fmt.Errorf("账单 %q 的第 %d 档合计与计价规则不符", key, i+1)
761			}
762		}
763		if b.TotalFee != priced.totalFee {
764			return fmt.Errorf("账单 %q 总金额与计价规则不符", key)
765		}
766		return nil
767	}
768	
769	// save 整体原子落盘：先写临时文件并同步，再 rename 覆盖。
770	// 只有完整保存成功后调用方才会向用户报告成功。
771	func (s *state) save() error {
772		if err := s.validate(); err != nil {
773			return fmt.Errorf("拒绝写入不一致的数据: %w", err)
774		}
775		data, err := json.MarshalIndent(s, "", "  ")
776		if err != nil {
777			return fmt.Errorf("序列化数据失败: %w", err)
778		}
779		data = append(data, '\n')
780	
781		tmp := s.path + ".tmp"
782		f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o644)
783		if err != nil {
784			return fmt.Errorf("写入临时数据文件失败: %w", err)
785		}
786		if _, err := f.Write(data); err != nil {
787			f.Close()
788			os.Remove(tmp)
789			return fmt.Errorf("写入临时数据文件失败: %w", err)
790		}
791		if err := f.Sync(); err != nil {
792			f.Close()
793			os.Remove(tmp)
794			return fmt.Errorf("同步数据文件失败: %w", err)
795		}
796		if err := f.Close(); err != nil {
797			os.Remove(tmp)
798			return fmt.Errorf("关闭数据文件失败: %w", err)
799		}
800		if err := os.Rename(tmp, s.path); err != nil {
801			os.Remove(tmp)
802			return fmt.Errorf("替换数据文件失败: %w", err)
803		}
804		if dir, err := os.Open(filepath.Dir(s.path)); err == nil {
805			dir.Sync()
806			dir.Close()
807		}
808		return nil
809	}
810	
811	func billKey(customerID, month string) string {
812		return customerID + "|" + month
813	}
814	
815	func planChangeKey(customerID, month string) string {
816		return customerID + "|" + month
817	}
818	
819	// planChangesFor 返回某客户的全部方案变更，按生效月升序。
820	func (s *state) planChangesFor(customerID string) []*planChange {
821		var list []*planChange
822		for _, ch := range s.PlanChanges {
823			if ch.CustomerID == customerID {
824				list = append(list, ch)
825			}
826		}
827		sort.Slice(list, func(i, j int) bool { return list[i].Month < list[j].Month })
828		return list
829	}
830	
831	// effectivePlanID 返回客户在某 UTC 自然月实际适用的阶梯方案标识：
832	// 创建时绑定的初始方案，被生效月不晚于该月的最后一次变更替换。
833	func (s *state) effectivePlanID(cust *customer, month string) string {
834		planID := cust.PlanID
835		latest := ""
836		for _, ch := range s.PlanChanges {
837			if ch.CustomerID == cust.ID && ch.Month <= month && ch.Month >= latest {
838				latest = ch.Month
839				planID = ch.PlanID
840			}
841		}
842		return planID
843	}
844	
845	// sealed 报告某客户的指定月份是否已封账。
846	func (s *state) sealed(customerID, month string) bool {
847		_, ok := s.Bills[billKey(customerID, month)]
848		return ok
849	}
850	
851	// adjustmentsFor 返回某客户某月账单的全部调整，按操作序号升序。
852	func adjustmentsFor(s *state, customerID, month string) []*adjustment {
853		var list []*adjustment
854		for _, a := range s.Adjustments {
855			if a.CustomerID == customerID && a.Month == month {
856				list = append(list, a)
857			}
858		}
859		sort.Slice(list, func(i, j int) bool { return list[i].Seq < list[j].Seq })
860		return list
861	}
862	
863	// correctionsFor 返回某收款的全部分配更正，按操作序号升序。
864	func correctionsFor(s *state, paymentID string) []*correction {
865		var list []*correction
866		for _, c := range s.Corrections {
867			if c.PaymentID == paymentID {
868				list = append(list, c)
869			}
870		}
871		sort.Slice(list, func(i, j int) bool { return list[i].Seq < list[j].Seq })
872		return list
873	}
874	
875	// currentAllocations 返回一笔收款当前生效的分配：无更正时为首次登记的
876	// 原始分配，否则为序号最大（最新）的更正的分配。
877	func currentAllocations(s *state, p *payment) []paymentAllocation {
878		var latest *correction
879		for _, c := range s.Corrections {
880			if c.PaymentID == p.ID && (latest == nil || c.Seq > latest.Seq) {
881				latest = c
882			}
883		}
884		if latest != nil {
885			return latest.Allocations
886		}
887		return p.Allocations
888	}
889	
890	// allocAmountFor 返回分配列表中指定月份的金额；无该月分配时为 0。
891	func allocAmountFor(allocs []paymentAllocation, month string) int64 {
892		for _, al := range allocs {
893			if al.Month == month {
894				return al.Amount
895			}
896		}
897		return 0
898	}
899	
900	// paymentsEverFor 返回历史上曾涉及某客户某月账单的全部收款（首次登记
901	// 分配或任一次更正的新分配涉及该月，即使后来被更正移出），按操作序号升序。
902	func paymentsEverFor(s *state, customerID, month string) []*payment {
903		var list []*payment
904		for _, p := range s.Payments {
905			if p.CustomerID != customerID {
906				continue
907			}
908			involved := p.amountFor(month) > 0
909			if !involved {
910				for _, c := range s.Corrections {
911					if c.PaymentID == p.ID && allocAmountFor(c.Allocations, month) > 0 {
912						involved = true
913						break
914					}
915				}
916			}
917			if involved {
918				list = append(list, p)
919			}
920		}
921		sort.Slice(list, func(i, j int) bool { return list[i].Seq < list[j].Seq })
922		return list
923	}
924	
925	// paymentReceived 返回全部未撤销收款按最新分配在指定月份计入的实收之和。
926	// 各笔分配均为正整数，用非负 64 位加法累加，溢出时返回错误。
927	func paymentReceived(s *state, customerID, month string) (int64, error) {
928		var received int64
929		for _, p := range s.Payments {
930			if p.CustomerID != customerID || p.Revoked {
931				continue
932			}
933			amt := allocAmountFor(currentAllocations(s, p), month)
934			if amt <= 0 {
935				continue
936			}
937			var err error
938			received, err = add64(received, amt)
939			if err != nil {
940				return 0, err
941			}
942		}
943		return received, nil
944	}
945	
946	// errPayableOutOfRange 表示当前应付越出 [0, 有符号 64 位最大值]。
947	var errPayableOutOfRange = errors.New("当前应付越界（须介于 0 与有符号 64 位最大值之间）")
948	
949	// billTotals 计算全部未撤销调整的净额与当前应付（原总金额 + 净额）。
950	// 净额按 128 位精确求和（与顺序无关），再校验应付落在
951	// [0, 有符号 64 位最大值] 内，全程整数运算。
952	func billTotals(b *bill, adjs []*adjustment) (net, payable int64, err error) {
953		var amounts []int64
954		for _, a := range adjs {
955			if !a.Revoked {
956				amounts = append(amounts, a.Amount)
957			}
958		}
959		net, err = sumSigned64(amounts...)
960		if err != nil {
961			return 0, 0, err
962		}
963		payable, err = addSigned64(b.TotalFee, net)
964		if err != nil {
965			return 0, 0, err
966		}
967		if payable < 0 {
968			return 0, 0, errPayableOutOfRange
969		}
970		return net, payable, nil
971	}
972

